15:Version 1.0 of the hal-engine WebSocket protocol. It covers, among other things, connection establishment, the message envelope used in both directions, the `SessionEntry` objects a conversation is built from, the entry lifecycle that orders them, the tool execution loop, the heartbeat and termination rules that bound a connection, and the protocol's security considerations. The `Status: Active` line in the block above is the protocol version's own status, distinct from the `Status` row of the header table, which tracks this spec's test-citation coverage under the convention in AGENTS.md § Spec Header Table.
41:Where `{basePath}` is the configurable path prefix (default `/hal`). A first connection has no id to offer and omits the query; a reconnect that wants its conversation back sends the `sessionId` from its previous `connected` frame. For example, with default settings:
48:The server validates only that the path begins with `{basePath}/ws`. The `sessionId` query parameter is read only when the server enables resume (`transport.resume`), and only if it is 1–128 characters of `[A-Za-z0-9_-]`. It is not a credential: the server rejoins that conversation only if it belongs to the connection's authenticated user, and answers any other id — someone else's, one it never issued, or one its store no longer holds — with a fresh session exactly as if no id had been sent. With `transport.resume.latest`, a connect that sends no id rejoins the user's most recently active conversation instead, unless it sends `?new=1`, which starts a new one. The server never adopts a requested id for a new session. See [the session resume spec](../hal-engine-session-resume/spec.md).
97:With resume enabled, the frame also carries `resumed`. On `resumed: true` it carries `entryCount`, and the server then replays the stored conversation before any other frame: one `entry_upsert` per entry at its own index, or an `entry_skip` for an entry a tool suppressed, so the client sees the conversation it saw live. When the connection named an id and was not resumed, the frame also carries `resumeFailure`: `expired` when the caller's own session aged out, `unknown` for every other case. With resume disabled none of these fields is present.
141:- The waiting message's model request therefore holds the earlier answer finished, never one still streaming ([validated by: hands the second run a history whose first answer is finished, never one still streaming](../../src/transport/ws/messageHandler.test.ts#L677)).
175:| `resumed`        | boolean  | Present only with resume enabled: whether the requested conversation was rejoined |
181:Creates a new entry or replaces an existing entry at the given index. This is the primary mechanism for adding content to the conversation.
255:Notifies the client that a session entry was created on the server and will never be sent. This happens under output suppression (see [tool-responses.md](../hal-engine-tool-responses/spec.md)): the server keeps the entry so the model retains context, and the client does not need it for display ([validated by: still records a suppressed reply in the session, so history keeps it](../../src/transport/ws/messageHandler.test.ts#L211)).
362:A SessionEntry represents a single piece of content in the conversation. Every entry has a `role` field that determines its shape. The `role` acts as a discriminant for the union type.
481:A typical conversation produces entries in this order:
634:- On reconnection, the client MUST clear its local entries array and SHOULD send `?sessionId=` with the id from its last `connected` frame. When the server has resume enabled and the conversation is the user's own, it answers `resumed: true` and replays the conversation; otherwise the client is starting a new session.
635:- An entry still streaming when its conversation is resumed is replayed with `isStreaming: false` and `truncated: true`: the rest of its turn streams to the connection that started it, so this one would wait for a commit that never comes ([validated by: replays an entry whose turn is still running as finished and truncated, leaving the stored entry as it is](../../src/transport/sessionResume.test.ts#L364)).
636:- With the server's `latest` option, a client that has lost the id, after a page refresh for instance, MAY connect without one and still rejoin its user's most recent conversation, and sends `?new=1` to start a new conversation instead ([validated by: with latest on, rejoins the most recently active session of a user whose connect names none](../../src/transport/sessionResume.test.ts#L428), [validated by: with latest on, starts a new session for a user with none, and on ?new=1 even when one exists](../../src/transport/sessionResume.test.ts#L445)).
import {jest} from '@jest/globals';
import net from 'node:net';
import {setLogger} from '../shared/logger.js';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {ExtWebSocket} from './ws/connectionHandler.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {WsAuthenticator} from '../types/auth.js';

// The defect this pins is an omission: both hooks are declared on HalServerOptions, and one was never forwarded.

const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));

const harness = (onConnect?: (session: ChatSession) => void) => {
  const sessionStore = {
    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
    delete: () => true,
  } as unknown as SessionStore;

  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: jest.fn() as unknown as WsAuthenticator,
    sessionStore,
    orchestrator: {} as ChatOrchestrator,
    onConnect,
  });

  const ws = {
    userId: 'u1',
    isAlive: true,
    send: () => undefined,
    on: () => undefined,
    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
    pause: () => undefined,
    resume: () => undefined,
    close: () => undefined,
  } as unknown as ExtWebSocket;

  return {hal, ws};
};

describe('createServer hook wiring', () => {
  it('forwards onConnect to the connection handler', async () => {
    const seen: ChatSession[] = [];
    const {hal, ws} = harness(session => void seen.push(session));

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(seen.length).toBe(1);
  });

  it('accepts a server configured without either hook', async () => {
    const {hal, ws} = harness();

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(hal.wss.listenerCount('connection')).toBe(1);
  });
});

// An EventEmitter with no `error` listener throws, so a socket error on a running server ended the process.
describe('a server error after start', () => {
  const engineLines: string[] = [];

  beforeEach(() => {
    engineLines.length = 0;
    const collect = (_category: string, message: string) => void engineLines.push(message);
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  const started = async () => {
    const {hal} = harness();
    await hal.start(0);
    return hal;
  };

  // A stopped engine and a port something else holds, so the next start is refused by the OS.
  const refusedStart = async () => {
    const hal = await started();
    await hal.stop();
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const release = () => new Promise<void>(resolve => blocker.close(() => resolve()));
    return {hal, taken, release};
  };

  it('is reported rather than ending the process', async () => {
    const hal = await started();

    hal.server.emit('error', new Error('late failure'));
    await hal.stop();

    expect(engineLines).toContain('server error after start');
  });

  it('leaves exactly one listener behind, however many times the server is restarted', async () => {
    const hal = await started();
    await hal.stop();
    await hal.start(0);

    const count = hal.server.listenerCount('error');
    await hal.stop();

    expect(count).toBe(1);
  });

  it('is still reported after stop, because an error with no handler ends the process', async () => {
    const hal = await started();
    await hal.stop();

    hal.server.emit('error', new Error('after stop'));

    expect(engineLines).toContain('server error after start');
  });

  it('is not reported for a start that was cleanly refused, because nothing was running', async () => {
    const {hal, taken, release} = await refusedStart();

    await hal.start(taken).catch((error: NodeJS.ErrnoException) => engineLines.push(`rejected ${error.code}`));
    await release();

    expect(engineLines).toEqual(['HAL Engine started', 'rejected EADDRINUSE']);
  });

  it('stops cleanly after a refused start, so a finally block does not turn one failure into two', async () => {
    const {hal, taken, release} = await refusedStart();
    await hal.start(taken).catch(() => undefined);

    const stopped = hal.stop().then(
      () => 'resolved',
      (error: NodeJS.ErrnoException) => `rejected ${error.code}`
    );
    await release();

    await expect(stopped).resolves.toBe('resolved');
  });

  it('refuses a second start without stripping the running server of its handler', async () => {
    const hal = await started();

    await hal.start(0).catch((error: Error) => engineLines.push(`rejected ${error.message}`));
    hal.server.emit('error', new Error('after the refused start'));
    await hal.stop();

    expect(engineLines).toEqual([
      'HAL Engine started',
      'rejected HAL Engine is already started',
      'server error after start',
    ]);
  });
});
